     2	
     3	/** Why a lookup produced no usable data. Mirrors GraphQL `WeatherFailureReason` (SPEC S5.5). */
     4	export type WeatherFailureReason =
     5	  | 'NETWORK'
     6	  | 'TIMEOUT'
     7	  | 'HTTP_ERROR'
     8	  | 'UPSTREAM_ERROR'
     9	  | 'INVALID_RESPONSE'
    10	  | 'LOCATION_MISMATCH';
