    14	      ok: true;
    15	      response: WeatherstackSuccess;
    16	      /** Body exactly as received (lat/lon still strings); used to record test fixtures. */
    17	      raw: unknown;
    18	    }
    19	  | {
    20	      ok: false;
    21	      reason: Exclude<WeatherFailureReason, 'LOCATION_MISMATCH'>;
    22	      /** For logs only. Never contains the access key; never sent to clients. */
    23	      detail: string;
    24	    };
    25	
    26	export interface WeatherstackClient {
    27	  /** Exactly one `/current` request; never throws. */
    28	  current(query: string): Promise<WeatherLookup>;
    29	}
    30	
    31	export interface WeatherstackClientOptions {
    32	  baseUrl: string;
    33	  accessKey: string;
    34	  timeoutMs?: number;
    35	}
    36	
    37	/** SPEC S5.5: no response within 5 s → TIMEOUT. */
    38	export const WEATHERSTACK_TIMEOUT_MS = 5000;
    39	
    40	const isTimeout = (error: unknown) =>
    41	  error instanceof DOMException && error.name === 'TimeoutError';
    42	
    43	/** Rejects with the signal's reason once it aborts, so no await can outlive the timeout. */
    44	const rejectOnAbort = (signal: AbortSignal) =>
    45	  new Promise<never>((_resolve, reject) => {
    46	    if (signal.aborted) reject(signal.reason);
    47	    signal.addEventListener('abort', () => reject(signal.reason), { once: true });
    48	  });
    49	
    50	export function createWeatherstackClient({
    51	  baseUrl,
    52	  accessKey,
    53	  timeoutMs = WEATHERSTACK_TIMEOUT_MS,
    54	}: WeatherstackClientOptions): WeatherstackClient {
    55	  const redact = (text: string) =>
    56	    text
    57	      .replaceAll(accessKey, '[redacted]')
    58	      .replaceAll(encodeURIComponent(accessKey), '[redacted]');
    59	  // Keep any path prefix on the base URL (e.g. a stub mounted under /weatherstack).
    60	  const endpoint = new URL('current', baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`);
    61	
    62	  return {
    63	    async current(query) {
    64	      const url = new URL(endpoint);
    65	      url.searchParams.set('access_key', accessKey);
    66	      url.searchParams.set('query', query);
    67	      url.searchParams.set('units', 'f');
    68	
    69	      const signal = AbortSignal.timeout(timeoutMs);
    70	      let response: Response;
    71	      try {
    72	        response = await fetch(url, { signal });
    73	      } catch (error) {
    74	        return {
    75	          ok: false,
    76	          reason: isTimeout(error) ? 'TIMEOUT' : 'NETWORK',
    77	          detail: redact(error instanceof Error ? error.message : String(error)),
    78	        };
    79	      }
    80	
    81	      if (!response.ok) {
    82	        return { ok: false, reason: 'HTTP_ERROR', detail: `HTTP ${response.status}` };
    83	      }
    84	
    85	      let body: unknown;
    86	      try {
    87	        body = await Promise.race([response.json(), rejectOnAbort(signal)]);
    88	      } catch (error) {
    89	        // The timeout also covers reading the body.
    90	        if (isTimeout(error))
    91	          return { ok: false, reason: 'TIMEOUT', detail: 'body read timed out' };
    92	        return { ok: false, reason: 'INVALID_RESPONSE', detail: 'body is not JSON' };
    93	      }
    94	
    95	      const upstreamError = WeatherstackError.safeParse(body);
    96	      if (upstreamError.success) {
    97	        const { code, type } = upstreamError.data.error ?? {};
    98	        return {
    99	          ok: false,
   100	          reason: 'UPSTREAM_ERROR',
   101	          detail: redact(`success:false code=${code ?? '?'} type=${type ?? '?'}`),
   102	        };
   103	      }
   104	
