509	    39	
510	    40	const isTimeout = (error: unknown) =>
511	    41	  error instanceof DOMException && error.name === 'TimeoutError';
512	    42	
513	    43	/** Rejects with the signal's reason once it aborts, so no await can outlive the timeout. */
514	    44	const rejectOnAbort = (signal: AbortSignal) =>
515	    45	  new Promise<never>((_resolve, reject) => {
516	    46	    if (signal.aborted) reject(signal.reason);
517	    47	    signal.addEventListener('abort', () => reject(signal.reason), { once: true });
518	    48	  });
519	    49	
520	    50	export function createWeatherstackClient({
521	    51	  baseUrl,
522	    52	  accessKey,
523	    53	  timeoutMs = WEATHERSTACK_TIMEOUT_MS,
524	    54	}: WeatherstackClientOptions): WeatherstackClient {
525	    55	  const redact = (text: string) =>
526	    56	    text
527	    57	      .replaceAll(accessKey, '[redacted]')
528	    58	      .replaceAll(encodeURIComponent(accessKey), '[redacted]');
529	    59	  // Keep any path prefix on the base URL (e.g. a stub mounted under /weatherstack).
530	    60	  const endpoint = new URL('current', baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`);
531	    61	
532	    62	  return {
533	    63	    async current(query) {
534	    64	      const url = new URL(endpoint);
535	    65	      url.searchParams.set('access_key', accessKey);
536	    66	      url.searchParams.set('query', query);
537	    67	      url.searchParams.set('units', 'f');
538	    68	
539	    69	      const signal = AbortSignal.timeout(timeoutMs);
540	    70	      let response: Response;
541	    71	      try {
542	    72	        response = await fetch(url, { signal });
543	    73	      } catch (error) {
544	    74	        return {
545	    75	          ok: false,
546	    76	          reason: isTimeout(error) ? 'TIMEOUT' : 'NETWORK',
547	    77	          detail: redact(error instanceof Error ? error.message : String(error)),
548	    78	        };
549	    79	      }
550	    80	
551	    81	      if (!response.ok) {
552	    82	        return { ok: false, reason: 'HTTP_ERROR', detail: `HTTP ${response.status}` };
553	    83	      }
554	    84	
555	    85	      let body: unknown;
556	    86	      try {
557	    87	        body = await Promise.race([response.json(), rejectOnAbort(signal)]);
558	    88	      } catch (error) {
559	    89	        // The timeout also covers reading the body.
560	    90	        if (isTimeout(error))
561	    91	          return { ok: false, reason: 'TIMEOUT', detail: 'body read timed out' };
562	    92	        return { ok: false, reason: 'INVALID_RESPONSE', detail: 'body is not JSON' };
563	    93	      }
564	    94	
565	    95	      const upstreamError = WeatherstackError.safeParse(body);
566	    96	      if (upstreamError.success) {
567	    97	        const { code, type } = upstreamError.data.error ?? {};
568	    98	        return {
569	    99	          ok: false,
570	   100	          reason: 'UPSTREAM_ERROR',
571	   101	          detail: redact(`success:false code=${code ?? '?'} type=${type ?? '?'}`),
572	   102	        };
573	   103	      }
574	   104	
575	   105	      const parsed = WeatherstackSuccess.safeParse(body);
576	   106	      if (!parsed.success) {
577	   107	        const paths = parsed.error.issues.map((issue) => issue.path.join('.')).join(', ');
578	   108	        return { ok: false, reason: 'INVALID_RESPONSE', detail: `invalid fields: ${paths}` };
579	   109	      }
580	   110	      return { ok: true, response: parsed.data, raw: body };
581	   111	    },
582	   112	  };
583	   113	}
