 32	  const [error, setError] = useState<string>();
 33	  const [deleteProperty, { loading }] = useMutation(DeletePropertyMutation, {
 34	    // Drop the record from the cache whether it was deleted now or already gone, so neither the
 35	    // list nor a revisited detail route can show it again (S6.6).
 36	    update(cache) {
 37	      cache.evict({ id: cache.identify({ __typename: 'Property', id }) });
