  1	import { useState } from 'react';
  2	import { useMutation } from '@apollo/client/react';
  3	import { useNavigate } from 'react-router';
  4	import { Trash2 } from 'lucide-react';
  5	import { toast } from 'sonner';
  6	import {
  7	  AlertDialog,
  8	  AlertDialogAction,
  9	  AlertDialogCancel,
 10	  AlertDialogContent,
 11	  AlertDialogDescription,
 12	  AlertDialogFooter,
 13	  AlertDialogHeader,
 14	  AlertDialogTitle,
 15	  AlertDialogTrigger,
 16	} from '@/components/ui/alert-dialog';
 17	import { Button } from '@/components/ui/button';
 18	import { DeletePropertyMutation } from './delete-property.mutation';
 19	
 20	/** S6.6 — confirm, delete, then return to the list the user came from. */
 21	export function DeletePropertyButton({
 22	  id,
 23	  address,
 24	  returnTo,
 25	}: {
 26	  id: string;
 27	  address: string;
 28	  returnTo: string;
 29	}) {
 30	  const navigate = useNavigate();
 31	  const [open, setOpen] = useState(false);
 32	  const [error, setError] = useState<string>();
 33	  const [deleteProperty, { loading }] = useMutation(DeletePropertyMutation, {
 34	    // Drop the record from the cache whether it was deleted now or already gone, so neither the
 35	    // list nor a revisited detail route can show it again (S6.6).
 36	    update(cache) {
 37	      cache.evict({ id: cache.identify({ __typename: 'Property', id }) });
 38	      cache.gc();
 39	    },
 40	  });
 41	
 42	  async function onConfirm() {
 43	    setError(undefined);
 44	    try {
 45	      await deleteProperty({ variables: { id } });
 46	      // DeletePropertySuccess and PropertyNotFoundError both mean the property no longer exists.
 47	      setOpen(false);
 48	      toast.success('Property deleted', { description: address });
 49	      await navigate(returnTo);
 50	    } catch {
 51	      setError('Could not reach the server. The property was not deleted.');
 52	    }
 53	  }
 54	
 55	  return (
 56	    <AlertDialog
 57	      open={open}
 58	      onOpenChange={(next) => {
 59	        if (loading) return;
 60	        setOpen(next);
 61	        setError(undefined);
 62	      }}
 63	    >
 64	      <AlertDialogTrigger asChild>
 65	        <Button variant="destructive">
 66	          <Trash2 />
 67	          Delete
 68	        </Button>
 69	      </AlertDialogTrigger>
 70	      <AlertDialogContent>
 71	        <AlertDialogHeader>
 72	          <AlertDialogTitle>Delete this property?</AlertDialogTitle>
 73	          <AlertDialogDescription>
 74	            {address} and its recorded weather will be removed. This can’t be undone.
 75	          </AlertDialogDescription>
 76	        </AlertDialogHeader>
 77	        {error && (
 78	          <p role="alert" className="text-sm text-destructive">
 79	            {error}
 80	          </p>
 81	        )}
 82	        <AlertDialogFooter>
 83	          <AlertDialogCancel disabled={loading}>Keep property</AlertDialogCancel>
 84	          <AlertDialogAction
 85	            variant="destructive"
 86	            disabled={loading}
 87	            onClick={(event) => {
 88	              // Stay open until the mutation settles so errors have somewhere to show.
 89	              event.preventDefault();
 90	              void onConfirm();
 91	            }}
 92	          >
 93	            {loading ? 'Deleting…' : 'Delete property'}
 94	          </AlertDialogAction>
 95	        </AlertDialogFooter>
 96	      </AlertDialogContent>
 97	    </AlertDialog>
 98	  );
 99	}
