 33	/** S3 — filters apply on submit, so a half-typed zip never reaches the API. */
 34	export function PropertyFilters({
 35	  applied,
 36	  onApply,
 37	}: {
 38	  applied: FilterValues;
 39	  onApply: (values: FilterValues) => void;
 40	}) {
 41	  const [draft, setDraft] = useState(applied);
 42	  const [zipError, setZipError] = useState<string>();
 43	  const [prevApplied, setPrevApplied] = useState(applied);
 44	
 45	  // Keep the inputs in sync when filters change from outside: the "no matches" clear button, or
 46	  // the URL (back/forward). Compared by value, since `applied` is re-read from the URL each render.
 47	  if (!sameFilter(applied, prevApplied)) {
 48	    setPrevApplied(applied);
 49	    setDraft(applied);
 50	    setZipError(undefined);
 51	  }
 52	
 53	  const update = (field: keyof FilterValues) => (value: string) =>
 54	    setDraft((current) => ({ ...current, [field]: value }));
 55	
 56	  function onSubmit(event: FormEvent<HTMLFormElement>) {
 57	    event.preventDefault();
 58	    const zip = draft.zipCode.trim();
 59	    if (zip && !/^\d{5}$/.test(zip)) {
 60	      setZipError('Zip code must be exactly 5 digits.');
 61	      return;
 62	    }
 63	    setZipError(undefined);
 64	    onApply(draft);
 65	  }
 66	
 67	  return (
 68	    <form
 69	      onSubmit={onSubmit}
 70	      noValidate
 71	      aria-label="Filter properties"
 72	      className="grid gap-3 rounded-xl p-4 ring-1 ring-foreground/10 sm:grid-cols-[2fr_1fr_1fr_auto] sm:items-start"
 73	    >
 74	      <div className="grid gap-1.5">
 75	        <Label htmlFor="filter-city">City</Label>
 76	        <Input
 77	          id="filter-city"
 78	          value={draft.city}
 79	          onChange={(e) => update('city')(e.target.value)}
 80	          placeholder="Any city"
 81	        />
 82	      </div>
 83	      <div className="grid gap-1.5">
 84	        <Label htmlFor="filter-zip">Zip code</Label>
