     1	import os from 'node:os';
     2	
     3	const R = '[REDACTED]';
     4	
     5	// Value character class that stops at quotes, whitespace, `&` and backslashes, so replacing
     6	// inside JSON-escaped text (raw .jsonl lines) never consumes an escape and never breaks the JSON.
     7	const VALUE = String.raw`[^\s"'&\\]+`;
     8	
     9	/** Ordered [pattern, replacement] rules. Applied to raw JSONL lines and rendered Markdown alike. */
    10	export const RULES = [
    11	  // Weatherstack puts the key in the query string.
    12	  [new RegExp(String.raw`(access_key=[REDACTED]\[REDACTED)${VALUE}`, 'gi'), `$1${R}`],
    13	  // KEY=[REDACTED] / SECRET=[REDACTED] / TOKEN=[REDACTED] / PASSWORD=[REDACTED] (env files, shell exports).
    14	  [
    15	    new RegExp(
    16	      String.raw`\b([A-Z0-9_]*(?:KEY|SECRET|TOKEN|PASSWORD|PASSWD)[A-Z0-9_]*)=(?!\[REDACTED)${VALUE}`,
    17	      'g',
    18	    ),
    19	    `$1=${R}`,
    20	  ],
    21	  [/(Bearer\s+)(?!\[REDACTED)[A-Za-z0-9._~+/=-]{8,}/g, `$1${R}`],
    22	  [/\bsk-ant-[A-Za-z0-9_-]{10,}/g, R],
    23	  [/\b(?:ghp|gho|ghs|github_pat|sk|pk)_[A-Za-z0-9_]{16,}/g, R],
    24	  // Credentials inside connection strings: postgres://[REDACTED]@host -> postgres://[REDACTED]@host
    25	  [
    26	    /\b((?:postgres(?:ql)?|mysql|mongodb(?:\+srv)?|redis):\/\/)(?!\[REDACTED)[^\s:/@"\\]+:[^\s@"\\]+@/g,
    27	    `$1${R}@`,
    28	  ],
